    {"chapter": "Economic Fundamentals", "chapter_num": 3, "question": "Purchasing Power Parity (PPP) suggests that in the long run:", "a": "All currencies should have the same interest rate", "b": "Exchange rates adjust so that identical goods cost the same in different countries", "c": "Countries with higher GDP have stronger currencies", "d": "Trade deficits lead to currency appreciation", "answer": "b", "explanation": "PPP holds that exchange rates should equalise the price of a standardised basket of goods across countries.", "difficulty": "Hard"},
    {"chapter": "Economic Fundamentals", "chapter_num": 3, "question": "A leading economic indicator provides information:", "a": "About past economic performance", "b": "That moves in advance of changes in the overall economy", "c": "About concurrent economic activity", "d": "Only about stock market performance", "answer": "b", "explanation": "Leading indicators, such as new orders or building permits, tend to change before the economy changes direction.", "difficulty": "Medium"},
    {"chapter": "Economic Fundamentals", "chapter_num": 3, "question": "Quantitative easing (QE) involves a central bank:", "a": "Raising interest rates to reduce money supply", "b": "Buying large amounts of financial assets to inject money into the economy", "c": "Issuing more government bonds to finance a deficit", "d": "Increasing reserve requirements for commercial banks", "answer": "b", "explanation": "QE is a non-conventional monetary policy where the central bank buys assets to inject liquidity when policy rates are near zero.", "difficulty": "Hard"},
    {"chapter": "Economic Fundamentals", "chapter_num": 3, "question": "Debt-to-GDP ratio is used to assess:", "a": "A company's level of leverage", "b": "A country's public debt relative to the size of its economy", "c": "The government's budget balance", "d": "The trade balance", "answer": "b", "explanation": "The debt-to-GDP ratio indicates how manageable a country's debt level is relative to its economic output.", "difficulty": "Medium"},
    {"chapter": "Economic Fundamentals", "chapter_num": 3, "question": "Which of the following best defines unemployment caused by people switching between jobs?", "a": "Structural unemployment", "b": "Cyclical unemployment", "c": "Frictional unemployment", "d": "Seasonal unemployment", "answer": "c", "explanation": "Frictional unemployment arises from the time lag involved when workers move between jobs.", "difficulty": "Easy"},
    {"chapter": "Economic Fundamentals", "chapter_num": 3, "question": "The interest rate parity condition links:", "a": "Domestic and foreign inflation rates", "b": "Domestic and foreign interest rates to expected changes in exchange rates", "c": "GDP growth and interest rates", "d": "Bond prices and stock prices", "answer": "b", "explanation": "Interest rate parity states that differences in interest rates between countries should equal expected exchange rate changes.", "difficulty": "Hard"},
    {"chapter": "Economic Fundamentals", "chapter_num": 3, "question": "Crowding out in economics occurs when:", "a": "Central bank money printing reduces private savings", "b": "Government borrowing raises interest rates and reduces private investment", "c": "High taxes cause businesses to relocate abroad", "d": "Exports exceed imports causing currency appreciation", "answer": "b", "explanation": "Crowding out occurs when increased government borrowing drives up interest rates, discouraging private sector investment.", "difficulty": "Hard"},

    # Chapter 4: Accounting and Financial Statements
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "The balance sheet of a company shows:", "a": "Revenue earned and expenses incurred over a period", "b": "Assets, liabilities, and shareholders' equity at a specific point in time", "c": "Cash inflows and outflows during a period", "d": "Changes in retained earnings over a year", "answer": "b", "explanation": "The balance sheet is a snapshot of a company's financial position at a specific date.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "The accounting equation is:", "a": "Revenue = Expenses + Profit", "b": "Assets = Liabilities + Shareholders' Equity", "c": "Assets = Revenue - Expenses", "d": "Liabilities = Assets + Equity", "answer": "b", "explanation": "The fundamental accounting equation states that a company's assets equal its liabilities plus shareholders' equity.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Depreciation is best described as:", "a": "A cash payment made to repair equipment", "b": "The systematic allocation of the cost of a tangible asset over its useful life", "c": "The market value decline of an asset", "d": "A provision for doubtful debts", "answer": "b", "explanation": "Depreciation allocates the cost of fixed assets over their useful economic lives on a non-cash basis.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Gross profit is calculated as:", "a": "Revenue minus operating expenses", "b": "Revenue minus cost of goods sold", "c": "Revenue minus all expenses including tax", "d": "Net profit plus depreciation", "answer": "b", "explanation": "Gross profit = Revenue - Cost of Goods Sold, before deducting operating expenses.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "The current ratio is a measure of:", "a": "Profitability", "b": "Short-term liquidity — the ability to meet current liabilities with current assets", "c": "Long-term solvency", "d": "Asset efficiency", "answer": "b", "explanation": "Current ratio = Current Assets / Current Liabilities; it measures ability to pay short-term obligations.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "A company has current assets of GHS 600,000 and current liabilities of GHS 400,000. Its current ratio is:", "a": "0.67", "b": "1.5", "c": "2.0", "d": "1.0", "answer": "b", "explanation": "Current ratio = 600,000 / 400,000 = 1.5, meaning the company has GHS 1.50 of current assets per GHS 1 of current liabilities.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Which financial statement shows a company's revenues, expenses, and profit over a period?", "a": "Balance sheet", "b": "Statement of cash flows", "c": "Income statement (profit and loss account)", "d": "Statement of changes in equity", "answer": "c", "explanation": "The income statement (P&L) records financial performance — revenues, costs, and profit — over a defined period.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "EBITDA stands for:", "a": "Earnings Before Interest, Taxes, Depreciation, and Amortisation", "b": "Earnings Before Income Tax and Dividend Assessment", "c": "Estimated Benefit Income Tax Dividend Allowance", "d": "Effective Base Interest Tax Debt Adjustment", "answer": "a", "explanation": "EBITDA = Earnings Before Interest, Taxes, Depreciation, and Amortisation; a proxy for operating cash earnings.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Which of the following is a non-cash expense?", "a": "Interest payments", "b": "Employee salaries", "c": "Depreciation", "d": "Rent expense", "answer": "c", "explanation": "Depreciation is a non-cash charge that reduces reported profit without involving an actual cash outflow.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Return on Equity (ROE) measures:", "a": "How efficiently a company uses all its assets to generate profit", "b": "The profit generated per cedi of shareholders' equity invested", "c": "The dividend payout per share", "d": "The debt level relative to equity", "answer": "b", "explanation": "ROE = Net Profit / Shareholders' Equity; it measures returns generated for equity investors.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "The debt-to-equity ratio measures:", "a": "The proportion of assets financed by debt relative to equity", "b": "The company's total debt as a percentage of revenue", "c": "Interest payments relative to operating profit", "d": "The number of shares outstanding relative to total debt", "answer": "a", "explanation": "D/E ratio = Total Debt / Shareholders' Equity; it indicates financial leverage.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Inventory turnover ratio measures:", "a": "How often a company replaces its inventory over a period", "b": "The value of inventory on the balance sheet", "c": "The profit margin on inventory sales", "d": "The days taken to collect receivables", "answer": "a", "explanation": "Inventory turnover = COGS / Average Inventory; it shows how efficiently inventory is managed.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Accrual accounting recognises revenue:", "a": "When cash is received", "b": "When it is earned, regardless of when cash is received", "c": "At the end of the financial year only", "d": "When the invoice is issued to the customer", "answer": "b", "explanation": "Under accrual accounting, revenue is recognised when earned (performance obligation met), not when cash changes hands.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Which of the following increases a company's cash flow from operations?", "a": "Increase in accounts receivable", "b": "Increase in accounts payable", "c": "Purchase of fixed assets", "d": "Repayment of a bank loan", "answer": "b", "explanation": "An increase in payables means cash that would have been paid is retained longer, increasing operating cash flow.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Goodwill on a balance sheet arises from:", "a": "A company having loyal customers", "b": "Paying more than the fair value of net assets when acquiring another company", "c": "Revaluation of intangible assets annually", "d": "Profits accumulated above a threshold", "answer": "b", "explanation": "Goodwill = Purchase price paid - Fair value of net identifiable assets acquired in a business combination.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "The quick ratio (acid-test ratio) excludes which current asset from the current ratio calculation?", "a": "Cash", "b": "Accounts receivable", "c": "Inventory", "d": "Short-term investments", "answer": "c", "explanation": "The quick ratio = (Current Assets - Inventory) / Current Liabilities; inventory is excluded as it is less liquid.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Net profit margin is calculated as:", "a": "Net profit / Revenue × 100", "b": "Gross profit / Revenue × 100", "c": "EBIT / Total assets × 100", "d": "Net profit / Total assets × 100", "answer": "a", "explanation": "Net profit margin = Net Profit / Revenue × 100; it shows what percentage of revenue is retained as profit.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Free cash flow to the firm (FCFF) is best described as:", "a": "Dividends paid to shareholders", "b": "Cash generated from operations after capital expenditures, available to all capital providers", "c": "Net income plus depreciation", "d": "Revenue minus cost of goods sold", "answer": "b", "explanation": "FCFF = Operating cash flow - Capital expenditures; it represents cash available to both debt and equity holders.", "difficulty": "Hard"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Under IFRS, property, plant, and equipment can be measured using:", "a": "Only historical cost model", "b": "Either the cost model or the revaluation model", "c": "Only fair value model", "d": "Net realisable value model only", "answer": "b", "explanation": "IFRS (IAS 16) allows PP&E to be carried at historical cost less depreciation or at revalued amounts.", "difficulty": "Hard"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Days Sales Outstanding (DSO) measures:", "a": "How many days inventory is held before being sold", "b": "The average number of days to collect payment after a sale", "c": "The average days to pay suppliers", "d": "The number of days revenue covers expenses", "answer": "b", "explanation": "DSO = (Accounts Receivable / Revenue) × 365; a lower DSO indicates faster collection of receivables.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Which of the following would improve a company's working capital?", "a": "Buying additional fixed assets with cash", "b": "Paying off a long-term loan", "c": "Collecting outstanding receivables", "d": "Declaring a large cash dividend", "answer": "c", "explanation": "Collecting receivables converts a current asset (receivable) to cash; working capital remains the same but improves liquidity.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "A company's retained earnings represent:", "a": "Cash held in the company's bank account", "b": "Cumulative net profits not distributed as dividends", "c": "Shares repurchased by the company", "d": "Long-term borrowings", "answer": "b", "explanation": "Retained earnings are the accumulated net profits kept in the business after paying dividends.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Interest coverage ratio is used to assess:", "a": "A company's profitability", "b": "A company's ability to service its interest obligations from operating earnings", "c": "Total debt relative to equity", "d": "Cash available to pay dividends", "answer": "b", "explanation": "Interest coverage = EBIT / Interest Expense; it measures how easily a company can pay interest on debt.", "difficulty": "Medium"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Which accounting principle requires that expenses be matched to the revenues they help generate?", "a": "Going concern principle", "b": "Matching principle (accruals basis)", "c": "Prudence principle", "d": "Materiality principle", "answer": "b", "explanation": "The matching principle requires expenses to be recorded in the same period as the revenues they helped earn.", "difficulty": "Easy"},
    {"chapter": "Accounting and Financial Statements", "chapter_num": 4, "question": "Return on Assets (ROA) measures:", "a": "Net profit as a proportion of total assets", "b": "Revenue generated per GHS of total assets", "c": "Profit relative to shareholders' equity", "d": "Asset turnover multiplied by gross margin", "answer": "a", "explanation": "ROA = Net Profit / Total Assets; it shows how efficiently management uses all assets to generate profit.", "difficulty": "Easy"},

    # Chapter 5: Fixed Income Securities
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A bond is best described as:", "a": "An ownership stake in a company", "b": "A debt instrument representing a loan made by an investor to a borrower", "c": "A government savings account", "d": "An insurance policy for investors", "answer": "b", "explanation": "A bond is a fixed income instrument representing a loan from the investor to the issuer, which promises periodic interest and principal repayment.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "The face value (par value) of a bond is:", "a": "The market price of the bond today", "b": "The amount the issuer promises to repay at maturity", "c": "The annual coupon payment", "d": "The yield to maturity", "answer": "b", "explanation": "Face (par) value is the principal amount repaid to the bondholder at maturity.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "When market interest rates rise, bond prices:", "a": "Rise proportionally", "b": "Remain unchanged", "c": "Fall", "d": "Become equal to face value", "answer": "c", "explanation": "Bond prices and interest rates have an inverse relationship; rising rates make existing bonds less attractive, reducing their price.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "The coupon rate of a bond is:", "a": "The yield to maturity", "b": "The annual interest payment as a percentage of the bond's face value", "c": "The market price of the bond as a percentage of par", "d": "The rate at which the bond's price changes", "answer": "b", "explanation": "The coupon rate is the annual interest payment divided by the face value of the bond.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A bond trading at a price above its face value is said to be trading:", "a": "At par", "b": "At a discount", "c": "At a premium", "d": "At yield", "answer": "c", "explanation": "A bond is at a premium when its market price exceeds its face value, typically when its coupon exceeds market yields.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Yield to Maturity (YTM) is best described as:", "a": "The coupon rate on the bond", "b": "The total return anticipated on a bond if held until maturity", "c": "The current price of the bond", "d": "The credit rating of the bond issuer", "answer": "b", "explanation": "YTM is the internal rate of return of a bond held to maturity, accounting for all coupon payments and capital gain/loss.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A zero-coupon bond:", "a": "Pays regular coupons but no principal at maturity", "b": "Pays no periodic interest but is issued at a discount and redeemed at face value", "c": "Has a variable interest rate", "d": "Is only issued by governments", "answer": "b", "explanation": "Zero-coupon bonds pay no periodic interest; they are sold at a discount and redeemed at par, with the return being the difference.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Duration of a bond measures:", "a": "The maturity date of the bond", "b": "The sensitivity of a bond's price to changes in interest rates", "c": "The annual coupon payment", "d": "The credit quality of the issuer", "answer": "b", "explanation": "Duration measures the weighted average time to receive a bond's cash flows and its price sensitivity to yield changes.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Which type of bond gives the issuer the right to repay the principal before the maturity date?", "a": "Convertible bond", "b": "Callable bond", "c": "Putable bond", "d": "Zero-coupon bond", "answer": "b", "explanation": "A callable bond gives the issuer the option to redeem the bond early, typically when interest rates fall.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Credit risk in bond investing refers to:", "a": "The risk that interest rates will rise", "b": "The risk that the bond issuer will default on interest or principal payments", "c": "The risk that inflation will exceed the coupon rate", "d": "The risk of being unable to sell the bond quickly", "answer": "b", "explanation": "Credit risk (default risk) is the probability that an issuer fails to make promised interest or principal payments.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A Ghana government bond is considered to have lower credit risk than a corporate bond because:", "a": "Government bonds pay higher coupons", "b": "The government can raise taxes or print money to service debt", "c": "Government bonds have shorter maturities", "d": "Government bonds are not subject to inflation risk", "answer": "b", "explanation": "Sovereign issuers can raise revenue through taxation or monetary means, making default less likely than for corporates.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "The yield curve shows the relationship between:", "a": "Bond prices and credit ratings", "b": "Interest rates (yields) and maturities for bonds of similar credit quality", "c": "Coupon rates and market prices", "d": "Duration and convexity", "answer": "b", "explanation": "The yield curve plots yields against maturities for comparable bonds, showing the term structure of interest rates.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "An inverted yield curve (short-term rates higher than long-term rates) is often interpreted as:", "a": "A sign of strong economic growth", "b": "A predictor of economic recession", "c": "A signal of rising inflation", "d": "Normal market conditions", "answer": "b", "explanation": "An inverted yield curve has historically been a reliable predictor of economic downturns.", "difficulty": "Hard"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A bond with a face value of GHS 1,000, a coupon rate of 15%, and annual payments has an annual coupon payment of:", "a": "GHS 100", "b": "GHS 150", "c": "GHS 1,150", "d": "GHS 115", "answer": "b", "explanation": "Annual coupon = 15% × GHS 1,000 = GHS 150.", "difficulty": "Easy"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Convexity in bond pricing refers to:", "a": "The curved shape of the yield curve", "b": "The non-linear relationship between bond price changes and yield changes", "c": "The difference between nominal and real yields", "d": "The credit spread above the risk-free rate", "answer": "b", "explanation": "Convexity measures the curvature in the price-yield relationship; bonds with higher convexity rise more and fall less for given yield changes.", "difficulty": "Hard"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A floating rate bond has:", "a": "A fixed coupon rate throughout its life", "b": "A coupon rate that resets periodically based on a reference interest rate", "c": "No coupon payments", "d": "A coupon tied to the stock market index", "answer": "b", "explanation": "Floating rate bonds have variable coupons that reset to a reference rate (e.g., LIBOR, policy rate) plus a spread.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Reinvestment risk for a bond investor is the risk that:", "a": "The bond issuer will call the bond early", "b": "Coupon payments received will be reinvested at lower rates than anticipated", "c": "Inflation erodes the bond's real return", "d": "The bond's credit rating will be downgraded", "answer": "b", "explanation": "Reinvestment risk is the risk that future cash flows will be reinvested at lower interest rates, reducing total return.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Which rating agency designation is considered investment grade?", "a": "BB and below (S&P)", "b": "BBB- and above (S&P)", "c": "C and above", "d": "D and above", "answer": "b", "explanation": "Investment grade bonds are rated BBB- (S&P/Fitch) or Baa3 (Moody's) and above; below is speculative/junk grade.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "The current yield of a bond is calculated as:", "a": "Annual coupon / Face value", "b": "Annual coupon / Current market price", "c": "YTM minus the inflation rate", "d": "Face value / Current market price", "answer": "b", "explanation": "Current yield = Annual coupon payment / Current market price of the bond.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Accrued interest on a bond represents:", "a": "Overdue interest payments by the issuer", "b": "Interest earned since the last coupon payment date, owed to the seller", "c": "The difference between coupon rate and yield", "d": "Penalty interest charged on late bond payments", "answer": "b", "explanation": "When a bond is sold between coupon dates, the buyer pays the seller accrued interest earned since the last payment.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Subordinated debt holders receive payment in the event of bankruptcy:", "a": "Before senior debt holders", "b": "After senior debt holders but before equity holders", "c": "After equity holders", "d": "At the same time as senior debt holders", "answer": "b", "explanation": "In the capital structure hierarchy, subordinated debt ranks below senior debt but above equity in liquidation.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A convertible bond gives the holder the right to:", "a": "Call back the bond from the issuer at par", "b": "Convert the bond into a specified number of ordinary shares", "c": "Exchange the bond for a higher-yielding bond", "d": "Demand early repayment of principal", "answer": "b", "explanation": "Convertible bonds can be exchanged for shares at a specified conversion ratio, offering equity upside.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "The spread between a corporate bond yield and a government bond yield of the same maturity is called:", "a": "Duration", "b": "The risk-free rate", "c": "The credit spread", "d": "The yield to call", "answer": "c", "explanation": "The credit spread compensates investors for the additional credit risk of holding corporate vs. risk-free government bonds.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "Ghana's Eurobonds are denominated in:", "a": "Ghana cedis", "b": "US dollars or other foreign currencies", "c": "Euros only", "d": "Special Drawing Rights (SDRs)", "answer": "b", "explanation": "Eurobonds are international bonds issued in a foreign currency; Ghana's Eurobonds are typically USD-denominated.", "difficulty": "Medium"},
    {"chapter": "Fixed Income Securities", "chapter_num": 5, "question": "A bond with longer maturity will generally have:", "a": "Lower interest rate risk", "b": "Higher interest rate risk (greater price sensitivity to rate changes)", "c": "The same interest rate risk as a shorter bond", "d": "No interest rate risk if held to maturity", "answer": "b", "explanation": "Longer maturity means a larger portion of cash flows are discounted over more periods, increasing price sensitivity to yield changes.", "difficulty": "Medium"},

    # Chapter 6: Equity Securities
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Ordinary (common) shares represent:", "a": "A debt obligation of the company", "b": "An ownership interest in a company with residual claims on profits and assets", "c": "A guaranteed fixed dividend payment", "d": "A short-term money market instrument", "answer": "b", "explanation": "Ordinary shareholders are the residual owners of a company, entitled to profits after all other claims are settled.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Preference shares differ from ordinary shares in that:", "a": "Preference shares carry voting rights", "b": "Preference shareholders receive dividends before ordinary shareholders", "c": "Preference shares have higher growth potential", "d": "Preference shareholders have residual claims on assets", "answer": "b", "explanation": "Preference shareholders have priority over ordinary shareholders for dividend payments and in liquidation.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Earnings Per Share (EPS) is calculated as:", "a": "Total revenue / Number of shares outstanding", "b": "Net profit attributable to ordinary shareholders / Weighted average number of ordinary shares", "c": "Dividends paid / Number of shares", "d": "Market price / Book value per share", "answer": "b", "explanation": "EPS = Net profit for ordinary shareholders / Weighted average shares outstanding; a key profitability metric.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "The Price-to-Earnings (P/E) ratio is calculated as:", "a": "Market price per share / Earnings per share", "b": "Earnings per share / Market price per share", "c": "Dividends per share / Market price per share", "d": "Book value per share / Market price per share", "answer": "a", "explanation": "P/E ratio = Market price per share / EPS; it indicates how much investors pay for each cedi of earnings.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "A high P/E ratio for a stock typically suggests:", "a": "The stock is undervalued", "b": "Investors expect high future earnings growth", "c": "The company pays high dividends", "d": "The stock has low risk", "answer": "b", "explanation": "A high P/E indicates investors are willing to pay a premium, typically expecting strong future earnings growth.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Dividend yield is calculated as:", "a": "Annual dividend per share / Market price per share × 100", "b": "Net profit / Number of shares × 100", "c": "Market price / Book value × 100", "d": "Earnings per share / Market price × 100", "answer": "a", "explanation": "Dividend yield = Annual DPS / Market price per share × 100; measures income return relative to share price.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "A bonus (scrip) issue involves:", "a": "Paying shareholders an extra cash dividend", "b": "Issuing additional free shares to existing shareholders from reserves", "c": "Offering shares to the public at a discount", "d": "Buying back shares from the market", "answer": "b", "explanation": "A bonus issue capitalises reserves by distributing free additional shares to existing shareholders proportionally.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "What is the theoretical ex-rights price (TERP)?", "a": "The price of a bond after coupon payment", "b": "The expected share price after a rights issue, based on weighted average of old and new shares", "c": "The stock price at which rights can be exercised", "d": "The market price before a dividend announcement", "answer": "b", "explanation": "TERP is the theoretical equilibrium price of shares after a rights issue, weighted by old and new shares.", "difficulty": "Hard"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Which of the following is NOT a benefit of being a listed company?", "a": "Access to capital markets", "b": "Enhanced corporate profile and credibility", "c": "Complete privacy of financial information", "d": "Improved liquidity for shareholders", "answer": "c", "explanation": "Listed companies must disclose financial information publicly; privacy is sacrificed as a cost of listing.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "The dividend cover ratio measures:", "a": "The number of years dividends have been paid", "b": "How many times the net profit covers the dividend paid", "c": "The dividend per share relative to the share price", "d": "The ratio of dividend income to capital gains", "answer": "b", "explanation": "Dividend cover = EPS / DPS; it shows how sustainable the dividend is relative to earnings.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Book value per share is calculated as:", "a": "Market capitalisation / Number of shares", "b": "Shareholders' equity / Number of shares outstanding", "c": "Net profit / Number of shares", "d": "Total assets / Number of shares", "answer": "b", "explanation": "Book value per share = Total shareholders' equity / Shares outstanding; represents accounting value per share.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "The Price-to-Book (P/B) ratio below 1.0 may indicate:", "a": "The stock is overvalued", "b": "The market values the company at less than its net asset value", "c": "The company has no debt", "d": "The company has a high dividend payout", "answer": "b", "explanation": "P/B < 1 means the stock trades below net asset value, which may signal undervaluation or fundamental problems.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Share buybacks (repurchases) typically:", "a": "Increase the total number of shares outstanding", "b": "Reduce the number of shares outstanding, potentially increasing EPS", "c": "Have no effect on earnings per share", "d": "Reduce the company's cash balance without affecting shareholders", "answer": "b", "explanation": "Share buybacks reduce outstanding shares; with same total earnings, EPS increases and can boost share price.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Cumulative preference shares are those where:", "a": "Dividends accumulate and must be paid before ordinary dividends if skipped", "b": "Dividends are compounded annually", "c": "Shareholders receive both preference and ordinary dividends", "d": "Dividends are only paid when the company is profitable", "answer": "a", "explanation": "Cumulative preference shares ensure that any unpaid dividends accumulate and must be settled before ordinary dividends.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Diluted EPS differs from basic EPS in that it:", "a": "Excludes extraordinary items", "b": "Accounts for the potential impact of convertible securities and share options on the share count", "c": "Is calculated before tax", "d": "Uses a smaller number of shares", "answer": "b", "explanation": "Diluted EPS adjusts for all potential shares from options, warrants, and convertibles, giving a conservative measure.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "The dividend payout ratio is:", "a": "Dividends paid / Net profit", "b": "Net profit / Number of shares", "c": "Market price / Dividends per share", "d": "Total dividends / Total assets", "answer": "a", "explanation": "Payout ratio = Dividends paid / Net profit; it shows the proportion of earnings distributed as dividends.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "A company's shares trade at GHS 5.00 on the GSE. Its EPS is GHS 0.50. The P/E ratio is:", "a": "2.5", "b": "10", "c": "0.1", "d": "5", "answer": "b", "explanation": "P/E = Market price / EPS = 5.00 / 0.50 = 10 times.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Equity risk premium is:", "a": "The return an equity investor demands above the risk-free rate", "b": "The premium paid by companies to list on the stock exchange", "c": "The extra dividend paid to preference shareholders", "d": "The difference between a company's book and market value", "answer": "a", "explanation": "The equity risk premium (ERP) compensates investors for the additional risk of equities over risk-free instruments.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "A company announces a 1-for-4 rights issue at GHS 2.00 when the current price is GHS 3.00. The theoretical ex-rights price is:", "a": "GHS 2.50", "b": "GHS 2.80", "c": "GHS 3.00", "d": "GHS 2.00", "answer": "b", "explanation": "TERP = [(4 × GHS 3.00) + (1 × GHS 2.00)] / 5 = (12 + 2) / 5 = GHS 2.80.", "difficulty": "Hard"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "The Gordon Growth Model (Dividend Discount Model) values a stock as:", "a": "Next dividend / (Required return + Growth rate)", "b": "Next dividend / (Required return - Growth rate)", "c": "Current dividend / Required return", "d": "EPS × P/E ratio", "answer": "b", "explanation": "Gordon Growth Model: P = D1 / (r - g), where D1 is next dividend, r is required return, g is constant growth rate.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Voting rights attached to ordinary shares give shareholders the power to:", "a": "Set the price of the company's shares", "b": "Elect the board of directors and vote on major corporate decisions", "c": "Receive guaranteed dividends", "d": "Access all the company's financial records at any time", "answer": "b", "explanation": "Ordinary shareholders exercise control through voting on directors and key resolutions at general meetings.", "difficulty": "Easy"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Enterprise Value (EV) is calculated as:", "a": "Market capitalisation only", "b": "Market capitalisation + Total debt - Cash and equivalents", "c": "Total assets - Total liabilities", "d": "Share price × Book value per share", "answer": "b", "explanation": "EV = Market cap + Total debt - Cash; it represents the total value of the company to all stakeholders.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Which of the following sectors is most represented on the Ghana Stock Exchange?", "a": "Technology", "b": "Mining and extractives", "c": "Banking and financial services", "d": "Agriculture", "answer": "c", "explanation": "The banking and financial services sector has the highest number and market capitalisation of listed companies on the GSE.", "difficulty": "Medium"},
    {"chapter": "Equity Securities", "chapter_num": 6, "question": "Participating preference shares entitle holders to:", "a": "Extra dividends beyond the fixed preference rate if ordinary dividends exceed a threshold", "b": "Convert shares to bonds at will", "c": "Vote at extraordinary general meetings", "d": "Receive dividends before the company pays taxes", "answer": "a", "explanation": "Participating preference shares allow holders to share in additional profits above a set level alongside ordinary shareholders.", "difficulty": "Hard"},

    # Chapter 7: Collective Investment Schemes
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "A collective investment scheme (CIS) pools funds from multiple investors to:", "a": "Provide individual investors with direct control over each investment", "b": "Invest collectively in a diversified portfolio managed by a professional fund manager", "c": "Guarantee fixed returns to all investors", "d": "Lend money to other investors", "answer": "b", "explanation": "CIS pools investor funds, enabling access to professional management, diversification, and economies of scale.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "A unit trust is an example of a:", "a": "Closed-end fund", "b": "Open-end collective investment scheme", "c": "Exchange-traded derivative", "d": "Hedge fund", "answer": "b", "explanation": "A unit trust is an open-end fund where units are created and redeemed based on investor demand at the prevailing NAV.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Net Asset Value (NAV) per unit is calculated as:", "a": "Total fund assets / Number of units outstanding", "b": "(Total assets - Total liabilities) / Number of units outstanding", "c": "Total income earned / Number of units outstanding", "d": "Market price of units / Number of investors", "answer": "b", "explanation": "NAV per unit = (Total assets - Liabilities) / Units outstanding; it is the price at which units are bought/redeemed.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "An open-end mutual fund differs from a closed-end fund in that:", "a": "It is not subject to regulation", "b": "It issues a fixed number of shares that trade on an exchange", "c": "It continuously issues and redeems units at the prevailing NAV", "d": "It only invests in fixed income securities", "answer": "c", "explanation": "Open-end funds issue/redeem units directly with investors at NAV; closed-end funds have fixed shares trading on exchanges.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "An Exchange-Traded Fund (ETF) differs from a traditional mutual fund in that:", "a": "ETFs invest only in bonds", "b": "ETFs are traded on stock exchanges throughout the day like ordinary shares", "c": "ETFs are not regulated by the SEC", "d": "ETFs guarantee capital protection", "answer": "b", "explanation": "ETFs trade on exchanges in real time during market hours, unlike mutual funds priced once daily at NAV.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "The fund manager of a unit trust has a fiduciary duty to:", "a": "Maximise the manager's own fees", "b": "Act in the best interests of the unit holders", "c": "Achieve the highest possible returns regardless of risk", "d": "Report only to the trustees", "answer": "b", "explanation": "Fund managers have a fiduciary duty to prioritise investors' interests above their own.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "A money market fund invests primarily in:", "a": "Equities and real estate", "b": "Short-term, high-quality debt instruments such as Treasury bills and commercial paper", "c": "Long-term government bonds only", "d": "International foreign currency assets", "answer": "b", "explanation": "Money market funds invest in short-term, liquid, low-risk instruments to preserve capital and provide liquidity.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Which entity typically holds the assets of a unit trust in Ghana on behalf of unit holders?", "a": "The fund manager", "b": "The Securities and Exchange Commission", "c": "The trustee (custodian)", "d": "The Ghana Stock Exchange", "answer": "c", "explanation": "A trustee (custodian) holds the fund assets separately from the fund manager to protect investor interests.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Dollar-cost averaging in a mutual fund means:", "a": "Investing a lump sum at the lowest possible price", "b": "Investing a fixed amount at regular intervals regardless of unit price", "c": "Adjusting investment based on the dollar exchange rate", "d": "Timing the market to buy at lows and sell at highs", "answer": "b", "explanation": "Dollar-cost averaging involves investing fixed amounts regularly, buying more units when prices are low and fewer when high.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "The total expense ratio (TER) of a fund represents:", "a": "The fund's total return before fees", "b": "All costs charged to the fund as a percentage of average net assets", "c": "The commission paid to the broker who sold the fund", "d": "The fund's portfolio turnover rate", "answer": "b", "explanation": "TER captures all ongoing costs (management fee, admin, custody, etc.) as a proportion of average fund value.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "A balanced (hybrid) fund typically invests in:", "a": "Only government bonds", "b": "Both equities and fixed income securities", "c": "Only cash and money market instruments", "d": "Foreign assets exclusively", "answer": "b", "explanation": "Balanced funds maintain a mix of equities and bonds to provide both growth potential and income stability.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Which of the following is an advantage of investing in a CIS compared to direct individual investment?", "a": "Higher returns are always guaranteed", "b": "Lower costs through economies of scale and professional management", "c": "Complete elimination of investment risk", "d": "Direct control over specific securities", "answer": "b", "explanation": "CIS offer professional management, diversification, and cost efficiencies unavailable to most small individual investors.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "A closed-end fund's shares typically trade:", "a": "Always at exactly NAV", "b": "At a premium or discount to NAV on the stock exchange", "c": "Only directly with the fund manager at NAV", "d": "At face value on the money market", "answer": "b", "explanation": "Closed-end fund shares trade on exchanges where supply and demand determine price, often diverging from NAV.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "In Ghana, collective investment schemes are governed and licensed by:", "a": "Bank of Ghana", "b": "Ghana Revenue Authority", "c": "Securities and Exchange Commission (SEC) Ghana", "d": "National Pensions Regulatory Authority", "answer": "c", "explanation": "SEC Ghana licenses and regulates fund managers and collective investment schemes under the Securities Industry Act.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "A fund with a front-end load charges:", "a": "A fee when units are redeemed", "b": "A fee at the time of purchasing units, reducing the initial investment", "c": "An annual fee deducted from fund assets", "d": "A performance fee when returns exceed a benchmark", "answer": "b", "explanation": "A front-end load is a sales charge paid upfront when buying fund units, reducing the amount actually invested.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Index funds aim to:", "a": "Outperform their benchmark index through active management", "b": "Replicate the performance of a specific market index at low cost", "c": "Protect investors against market downturns", "d": "Invest only in the largest companies by market capitalisation", "answer": "b", "explanation": "Index funds passively track a benchmark index, offering market returns at lower fees than active management.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Which type of fund is typically most suitable for an investor with a very short-term horizon?", "a": "Equity growth fund", "b": "Money market fund", "c": "Real estate investment trust", "d": "Private equity fund", "answer": "b", "explanation": "Money market funds invest in liquid short-term instruments, making them ideal for investors needing near-term access to funds.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "A fund prospectus is a legal document that:", "a": "Guarantees the performance of the fund", "b": "Discloses key information about the fund including objectives, risks, fees, and manager", "c": "Is only required when the fund is closed", "d": "Is the same as the fund's annual report", "answer": "b", "explanation": "A prospectus provides potential investors with material information to make informed investment decisions.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Real Estate Investment Trusts (REITs) allow investors to:", "a": "Directly own commercial properties", "b": "Invest in real estate assets collectively and receive income distributions", "c": "Avoid all taxes on property income", "d": "Only invest in residential properties", "answer": "b", "explanation": "REITs pool investor funds to invest in income-generating real estate and typically distribute most income to investors.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "The performance benchmark of an equity fund in Ghana would most likely be:", "a": "The 91-day Treasury bill rate", "b": "The GSE Composite Index", "c": "The Bank of Ghana policy rate", "d": "The consumer price index", "answer": "b", "explanation": "An equity fund investing on the GSE would benchmark its performance against the GSE Composite Index.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Redemption of unit trust units means:", "a": "The fund manager buys more units for investors", "b": "An investor sells their units back to the fund at the prevailing NAV", "c": "The fund distributes profits to investors", "d": "The fund is liquidated and closed", "answer": "b", "explanation": "Redemption involves the investor selling units back to the fund at the current NAV, receiving cash.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Which of the following best describes a fund of funds?", "a": "A fund that invests directly in shares and bonds", "b": "A fund that invests in other funds rather than directly in securities", "c": "A fund guaranteed by the government", "d": "A fund that only invests offshore", "answer": "b", "explanation": "A fund of funds achieves diversification by investing in a portfolio of other managed funds.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Investment in a CIS is best described as:", "a": "A deposit and therefore covered by deposit insurance", "b": "A capital market investment subject to market risk", "c": "A savings account with a guaranteed rate", "d": "A government-backed scheme", "answer": "b", "explanation": "CIS investments are capital market instruments exposed to market risk and are not bank deposits or guaranteed.", "difficulty": "Medium"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "The minimum investment amount in Ghana's unit trusts is typically:", "a": "GHS 1,000,000", "b": "Set by each fund manager but often relatively low to encourage retail participation", "c": "GHS 100,000", "d": "The same as the current NAV", "answer": "b", "explanation": "Fund managers set their own minimums; many Ghana unit trusts have low entry points to promote inclusivity.", "difficulty": "Easy"},
    {"chapter": "Collective Investment Schemes", "chapter_num": 7, "question": "Which statement about a no-load fund is correct?", "a": "It charges no management fees", "b": "It charges no sales commissions (front or back-end loads)", "c": "It has no minimum investment requirement", "d": "It carries no investment risk", "answer": "b", "explanation": "A no-load fund does not charge sales commissions; management and other operational fees may still apply.", "difficulty": "Medium"},

    # Chapter 8: Regulation and Governance
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The primary objective of the Securities and Exchange Commission (SEC) Ghana is to:", "a": "Maximise returns for investors", "b": "Regulate, supervise, and develop the securities industry to protect investors", "c": "Set interest rates for the capital market", "d": "Manage the Ghana Stock Exchange", "answer": "b", "explanation": "SEC Ghana's mandate is to regulate the securities industry, protect investors, and develop the capital market.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Know Your Customer (KYC) requirements in the financial industry require firms to:", "a": "Maintain a list of all stock prices", "b": "Verify and maintain records of clients' identities and understand the nature of their activities", "c": "Know the personal preferences of clients for marketing purposes", "d": "Lend to any customer who requests funds", "answer": "b", "explanation": "KYC involves verifying client identity, understanding their risk profile, and monitoring for suspicious activity.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Anti-Money Laundering (AML) regulations are designed to:", "a": "Prevent market manipulation in equity markets", "b": "Prevent criminals from disguising illegally obtained funds as legitimate income", "c": "Regulate dividend payments by listed companies", "d": "Control foreign currency transactions only", "answer": "b", "explanation": "AML regulations aim to detect and prevent the laundering of proceeds from criminal activities through financial systems.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Insider trading is best described as:", "a": "Trading securities based on publicly available information", "b": "Trading securities based on material, non-public information for personal gain", "c": "Trading large volumes of shares on the open market", "d": "A legal practice when disclosed to the regulator", "answer": "b", "explanation": "Insider trading involves using material, non-public information to trade securities, which is illegal and unfair to other investors.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The Ghana Stock Exchange (GSE) Listing Rules require listed companies to:", "a": "Pay dividends every quarter", "b": "Maintain minimum standards of disclosure, corporate governance, and financial performance", "c": "Hire only Ghanaian directors", "d": "Maintain a fixed share price", "answer": "b", "explanation": "GSE Listing Rules set disclosure, governance, and ongoing obligations for listed companies to protect investors.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "A Suspicious Transaction Report (STR) is filed when:", "a": "A company reports its annual profit", "b": "A financial institution suspects a transaction is related to money laundering or terrorism financing", "c": "An investor loses money on a transaction", "d": "The regulator audits a financial institution", "answer": "b", "explanation": "STRs are mandatory reports filed by financial institutions when transactions raise suspicion of financial crime.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The fit and proper test for securities market participants assesses:", "a": "The physical fitness of employees", "b": "Whether individuals and companies meet standards of competence, integrity, and financial soundness", "c": "The profitability of market participants", "d": "The age and experience of investors", "answer": "b", "explanation": "The fit and proper test ensures that market participants have the necessary integrity, competence, and financial standing.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Market manipulation includes which of the following?", "a": "Trading based on publicly released research reports", "b": "Creating artificial price movements through fictitious transactions or coordinated buying/selling", "c": "Diversifying a portfolio across different asset classes", "d": "Purchasing Treasury bills at auction", "answer": "b", "explanation": "Market manipulation involves artificially influencing prices through deceptive practices, which is illegal.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Corporate governance refers to:", "a": "The government's regulation of corporations", "b": "The system of rules, practices, and processes by which a company is directed and controlled", "c": "The management of a company's investment portfolio", "d": "The accounting standards applied to financial statements", "answer": "b", "explanation": "Corporate governance encompasses the framework for accountability, fairness, and transparency in company management.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The Financial Intelligence Centre (FIC) in Ghana is responsible for:", "a": "Setting monetary policy", "b": "Receiving and analysing financial intelligence related to money laundering and terrorist financing", "c": "Regulating insurance companies", "d": "Collecting taxes on investment income", "answer": "b", "explanation": "The FIC receives, analyses, and disseminates financial intelligence to combat financial crimes in Ghana.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Disclosure obligations for listed companies in Ghana include:", "a": "Publishing their complete employee database", "b": "Timely publication of material information such as financial results and significant events", "c": "Revealing the personal finances of all directors", "d": "Publishing all client transaction data", "answer": "b", "explanation": "Listed companies must disclose material information to ensure all investors have equal access to price-sensitive data.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The Securities Industry Act, 2016 (Act 929) provides the legal framework for:", "a": "Banking and credit regulation in Ghana", "b": "The regulation of the securities industry, including licensing and market conduct", "c": "Tax collection on capital gains", "d": "Insurance and pension regulation", "answer": "b", "explanation": "Act 929 is the primary legislation governing Ghana's securities industry, covering licensing, conduct, and enforcement.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The role of the board of directors in corporate governance is to:", "a": "Manage the day-to-day operations of the company", "b": "Oversee management, set strategy, and protect shareholders' interests", "c": "Prepare and sign off on financial statements", "d": "Represent the company in court", "answer": "b", "explanation": "The board provides strategic direction, oversight of management, and accountability to shareholders.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "An independent director on a board is one who:", "a": "Is appointed by the largest shareholder", "b": "Has no material relationship with the company that could compromise objectivity", "c": "Chairs all board committees", "d": "Is always a non-executive director of another listed company", "answer": "b", "explanation": "Independent directors have no material ties to the company, enabling objective judgment free from conflicts of interest.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The concept of 'Treating Customers Fairly' (TCF) in financial services means:", "a": "Offering the lowest fees in the market", "b": "Ensuring products and services are suitable for customers and customers are treated with integrity", "c": "Giving equal dividends to all customers", "d": "Providing free investment advice", "answer": "b", "explanation": "TCF requires firms to ensure fair outcomes for customers, providing suitable products and honest service.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Politically Exposed Persons (PEPs) in AML regulations refer to:", "a": "Foreign investors only", "b": "Individuals who hold or have held prominent public positions and their associates", "c": "Company directors of listed firms", "d": "High-net-worth individuals with assets above GHS 10 million", "answer": "b", "explanation": "PEPs are individuals in high public positions (politicians, officials) who face higher money laundering risk due to their influence.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The purpose of a suitability assessment in investment advice is to:", "a": "Ensure the investment firm generates maximum commissions", "b": "Verify that recommended products are appropriate given the client's financial situation, goals, and risk tolerance", "c": "Comply with tax regulations", "d": "Determine the client's net worth for regulatory reporting", "answer": "b", "explanation": "Suitability assessment ensures investment recommendations match the client's objectives, risk profile, and circumstances.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "Which of the following best describes a prospectus as required by SEC Ghana?", "a": "A document listing all shareholders of a company", "b": "A formal legal document providing details of a security offering to enable informed investment decisions", "c": "A quarterly financial performance report", "d": "A contract between a broker and investor", "answer": "b", "explanation": "A prospectus is a legal disclosure document required for public offerings of securities, containing key risk and financial information.", "difficulty": "Easy"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "The principle of 'best execution' in securities trading requires brokers to:", "a": "Always achieve the lowest possible price when selling", "b": "Execute client orders on the best available terms, considering price, speed, and costs", "c": "Complete all orders within 24 hours", "d": "Match all buy and sell orders internally", "answer": "b", "explanation": "Best execution requires brokers to take all reasonable steps to obtain the best possible result for clients.", "difficulty": "Medium"},
    {"chapter": "Regulation and Governance", "chapter_num": 8, "question": "An investment adviser in Ghana must be licensed by:", "a": "Bank of Ghana", "b": "Securities and Exchange Commission Ghana", "c": "Ghana Revenue Authority", "d": "National Pensions Regulatory Authority", "answer": "b", "explanation": "Investment advisers providing advice on capital market instruments must be licensed by SEC Ghana.", "difficulty": "Easy"},
