    # Chapter 9: Risk and Return
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Systematic risk is defined as:", "a": "Risk unique to a specific company or industry", "b": "Market-wide risk that affects all securities and cannot be eliminated by diversification", "c": "Risk arising from poor management decisions", "d": "Risk that can be insured against", "answer": "b", "explanation": "Systematic (market) risk arises from economy-wide factors and cannot be diversified away.", "difficulty": "Easy"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Unsystematic (specific) risk is:", "a": "Risk that affects the entire market simultaneously", "b": "Company or industry-specific risk that can be reduced through diversification", "c": "Risk associated with changes in interest rates", "d": "The risk of currency depreciation", "answer": "b", "explanation": "Unsystematic risk is unique to a particular company or sector and can be diversified away.", "difficulty": "Easy"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Beta (β) in finance measures:", "a": "The total risk of a security", "b": "A security's volatility relative to the overall market", "c": "The credit risk of a bond", "d": "The liquidity of a security", "answer": "b", "explanation": "Beta measures systematic risk — how much a security's return moves relative to a 1% change in the market return.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "A stock with a beta of 1.5 means:", "a": "It moves 50% less than the market", "b": "It is expected to move 1.5% for every 1% movement in the market", "c": "It has 1.5 times less risk than the market", "d": "Its return is 1.5% above the risk-free rate", "answer": "b", "explanation": "A beta of 1.5 indicates the stock is 50% more volatile than the market; it amplifies market movements.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "The Capital Asset Pricing Model (CAPM) formula for expected return is:", "a": "E(R) = Risk-free rate + Beta × (Market return - Risk-free rate)", "b": "E(R) = Risk-free rate / Beta", "c": "E(R) = Dividend / Price + Growth rate", "d": "E(R) = Beta × Market return", "answer": "a", "explanation": "CAPM: E(R) = Rf + β(Rm - Rf), where Rf is the risk-free rate, β is beta, and (Rm - Rf) is the equity risk premium.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Standard deviation as a measure of investment risk captures:", "a": "Only the downside risk of a portfolio", "b": "The total variability of returns around the mean (both upside and downside)", "c": "The systematic risk of the portfolio", "d": "The probability of default", "answer": "b", "explanation": "Standard deviation measures total dispersion of returns around the average, representing total portfolio risk.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "The Sharpe Ratio measures:", "a": "Return per unit of systematic risk", "b": "Excess return over the risk-free rate per unit of total risk (standard deviation)", "c": "The probability of achieving a target return", "d": "Portfolio return minus benchmark return", "answer": "b", "explanation": "Sharpe Ratio = (Portfolio return - Risk-free rate) / Standard deviation; it measures risk-adjusted performance.", "difficulty": "Medium"},
