    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Adding assets with low or negative correlation to a portfolio:", "a": "Increases the portfolio's expected return", "b": "Increases the portfolio's total risk", "c": "Reduces the portfolio's overall risk without necessarily reducing expected return", "d": "Has no effect on portfolio risk", "answer": "c", "explanation": "Low/negative correlation assets reduce portfolio risk through diversification without proportionally reducing returns.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "The risk-free rate in Ghana is best approximated by:", "a": "The Bank of Ghana policy rate", "b": "The yield on 91-day Ghana government Treasury bills", "c": "The average bank lending rate", "d": "The Ghana inflation rate", "answer": "b", "explanation": "The 91-day T-bill rate is used as the risk-free rate in Ghana as it is a short-term, default-free government instrument.", "difficulty": "Easy"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "A stock has a beta of 0.7. This means:", "a": "It is more volatile than the market", "b": "It is less volatile than the market (defensive stock)", "c": "It is negatively correlated with the market", "d": "It has no systematic risk", "answer": "b", "explanation": "Beta < 1 means the stock moves less than the market; it is considered defensive (e.g., utilities, consumer staples).", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "The expected return on a portfolio is:", "a": "The return of the best-performing asset in the portfolio", "b": "The weighted average of the expected returns of the individual assets", "c": "The median return across all portfolio assets", "d": "The risk-free rate plus a fixed premium", "answer": "b", "explanation": "Portfolio expected return = sum of (weight × expected return) for each asset in the portfolio.", "difficulty": "Easy"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Liquidity risk in investing refers to:", "a": "The risk that a company becomes insolvent", "b": "The risk of not being able to sell an investment quickly at a fair price", "c": "The risk of loss from interest rate changes", "d": "The risk of currency depreciation", "answer": "b", "explanation": "Liquidity risk is the risk that an asset cannot be sold quickly enough without incurring a significant loss in value.", "difficulty": "Easy"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Country risk in international investing includes:", "a": "The risk of natural disasters only", "b": "Political instability, currency risk, regulatory changes, and economic instability in a foreign country", "c": "The risk of a foreign company defaulting on debt", "d": "Foreign exchange transaction costs", "answer": "b", "explanation": "Country risk encompasses political, economic, currency, and legal risks specific to investing in a particular country.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "The Treynor Ratio measures:", "a": "Excess return over the risk-free rate per unit of systematic risk (beta)", "b": "Excess return over the risk-free rate per unit of total risk", "c": "Return relative to benchmark", "d": "Standard deviation of returns", "answer": "a", "explanation": "Treynor Ratio = (Portfolio return - Risk-free rate) / Beta; uses systematic risk rather than total risk.", "difficulty": "Hard"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Value at Risk (VaR) measures:", "a": "The maximum possible loss on a portfolio", "b": "The maximum expected loss over a specified period at a given confidence level", "c": "The average return on a portfolio", "d": "The probability that a portfolio will outperform the market", "answer": "b", "explanation": "VaR estimates the maximum potential loss over a period (e.g., 1 day) at a specific confidence level (e.g., 95%).", "difficulty": "Hard"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Reinvestment risk is most relevant for which type of investor?", "a": "An equity investor seeking capital gains", "b": "A bond investor who needs to reinvest coupon payments", "c": "A real estate investor", "d": "A commodity futures trader", "answer": "b", "explanation": "Bond investors face reinvestment risk when coupon payments must be reinvested at potentially lower prevailing rates.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Which of the following portfolios has the best risk-adjusted return?", "a": "Portfolio A: 15% return, 10% standard deviation", "b": "Portfolio B: 18% return, 20% standard deviation", "c": "Portfolio C: 12% return, 6% standard deviation, risk-free rate 5%", "d": "Need to calculate Sharpe ratio to compare", "answer": "d", "explanation": "Risk-adjusted comparison requires calculating Sharpe ratios: A=(15-5)/10=1.0, B=(18-5)/20=0.65, C=(12-5)/6=1.17 — C is best.", "difficulty": "Hard"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Concentration risk in a portfolio arises from:", "a": "Holding too many different assets", "b": "Having too large a proportion of the portfolio in a single asset, sector, or region", "c": "Investing in low-liquidity assets", "d": "Holding only government bonds", "answer": "b", "explanation": "Concentration risk is excessive exposure to a single investment or related group, amplifying potential losses.", "difficulty": "Easy"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "The efficient frontier represents:", "a": "Portfolios that maximise return for a given level of risk", "b": "The set of all possible asset combinations", "c": "Only the highest-returning portfolio", "d": "The minimum variance portfolio only", "answer": "a", "explanation": "The efficient frontier is the set of optimal portfolios offering maximum expected return for each level of risk.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Currency risk affects investments when:", "a": "A domestic company raises its prices", "b": "Returns on foreign investments are affected by changes in exchange rates", "c": "Interest rates change in the home country", "d": "Inflation exceeds the investment return", "answer": "b", "explanation": "Currency risk occurs when exchange rate movements reduce the value of returns from foreign investments when converted back.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Jensen's Alpha measures:", "a": "The portfolio's total return", "b": "The excess return of a portfolio above what CAPM would predict given its systematic risk", "c": "The portfolio's standard deviation", "d": "The ratio of return to benchmark return", "answer": "b", "explanation": "Jensen's Alpha = Actual return - CAPM expected return; positive alpha indicates superior risk-adjusted performance.", "difficulty": "Hard"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "Which of the following is NOT a component of total risk of a single security?", "a": "Systematic risk", "b": "Unsystematic risk", "c": "Reinvestment risk", "d": "Regulatory risk", "answer": "c", "explanation": "Total risk = systematic + unsystematic risk. Reinvestment risk is a separate form not decomposed in this framework.", "difficulty": "Medium"},
    {"chapter": "Risk and Return", "chapter_num": 9, "question": "A portfolio with a beta of 1 has:", "a": "No systematic risk", "b": "The same systematic risk as the overall market", "c": "Double the systematic risk of the market", "d": "No correlation with the market", "answer": "b", "explanation": "A beta of exactly 1 means the portfolio moves in line with the overall market and has equivalent systematic risk.", "difficulty": "Easy"},

