    # Chapter 9: Mergers and Acquisitions
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A horizontal merger is between:", "a": "A company and its supplier", "b": "Two companies in the same industry and at the same stage of the supply chain", "c": "A company and one of its customers", "d": "A conglomerate and a start-up", "answer": "b", "explanation": "Horizontal mergers combine direct competitors in the same industry to gain market share and economies of scale.", "difficulty": "Easy"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A vertical merger combines:", "a": "Two unrelated companies in different industries", "b": "A company with its supplier or customer along the supply chain", "c": "Two direct competitors in the same market", "d": "A domestic and a foreign company", "answer": "b", "explanation": "Vertical mergers integrate upstream (suppliers) or downstream (customers) operations to control the supply chain.", "difficulty": "Easy"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Synergies in M&A are the additional value created when two companies combine. Which type involves reducing overlapping operations?", "a": "Revenue synergies", "b": "Cost synergies", "c": "Financial synergies", "d": "Market power synergies", "answer": "b", "explanation": "Cost synergies arise from eliminating redundant operations, workforce, and overhead when two companies merge.", "difficulty": "Easy"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Due diligence in M&A involves:", "a": "Marketing the deal to potential investors", "b": "A thorough investigation and verification of a target company's financial, legal, and operational details", "c": "Negotiating the final purchase price only", "d": "Obtaining regulatory approval from SEC Ghana", "answer": "b", "explanation": "Due diligence allows the acquirer to verify the target's disclosed information, identify risks, and validate valuation assumptions.", "difficulty": "Easy"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "An acquirer's NPV from an M&A transaction is positive when:", "a": "The deal is announced publicly", "b": "The present value of synergies exceeds the premium paid over the target's standalone value", "c": "The target company is profitable", "d": "The acquisition is financed entirely with debt", "answer": "b", "explanation": "M&A creates value for the acquirer when PV(synergies) > acquisition premium paid; otherwise value is destroyed.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A leveraged buyout (LBO) model primarily focuses on:", "a": "Future dividend payments to shareholders", "b": "The ability to service debt from the target's cash flows and exit at a profitable multiple", "c": "The target's current P/E ratio", "d": "Revenue synergies with the acquirer", "answer": "b", "explanation": "LBO viability depends on whether operating cash flows can service acquisition debt and generate sufficient IRR for equity investors at exit.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A tender offer in M&A is:", "a": "An offer made to management to incentivise retention", "b": "A public offer made directly to shareholders to buy their shares at a premium to the market price", "c": "An offer to buy a company's debt at below par", "d": "A proposal to merge without any cash payment", "answer": "b", "explanation": "A tender offer bypasses the target's board and goes directly to shareholders, offering a premium to encourage share sale.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A poison pill (shareholder rights plan) is a takeover defence that:", "a": "Requires the acquirer to pay a higher tax on deal proceeds", "b": "Allows existing shareholders to buy new shares at a discount if a hostile bidder acquires a threshold stake, diluting the bidder", "c": "Locks the target's key assets in a trust", "d": "Requires a supermajority vote to approve any acquisition", "answer": "b", "explanation": "Poison pills dilute a hostile bidder's stake by enabling existing shareholders to buy shares cheaply, making the acquisition prohibitively expensive.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "The accretion/dilution analysis in M&A determines:", "a": "Whether the deal creates or destroys shareholder value based on IRR", "b": "Whether the deal increases (accretive) or decreases (dilutive) the acquirer's EPS post-acquisition", "c": "The tax impact of the acquisition on the target", "d": "Whether synergies are achievable within the first year", "answer": "b", "explanation": "Accretion/dilution analysis tests whether EPS increases (accretive) or decreases (dilutive) after the deal closes.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A white knight in a hostile takeover is:", "a": "A financial adviser who values the target", "b": "A friendly acquirer invited by the target's board as an alternative to the hostile bidder", "c": "The target company's largest institutional shareholder", "d": "A regulatory authority that reviews the deal", "answer": "b", "explanation": "A white knight is a preferred acquirer sought by target management to prevent a hostile takeover from an unwanted bidder.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "The purchase price allocation (PPA) in an acquisition:", "a": "Allocates the purchase price among the acquirer's existing shareholders", "b": "Identifies and values all acquired tangible and intangible assets, with any excess recorded as goodwill", "c": "Determines the dividend policy post-acquisition", "d": "Allocates synergy benefits between the two companies", "answer": "b", "explanation": "PPA allocates the acquisition price to identifiable assets (including intangibles like brands) and liabilities, with excess as goodwill.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Earnout provisions in M&A deals:", "a": "Require the acquirer to pay dividends to the target's former shareholders", "b": "Tie a portion of the purchase price to future performance milestones of the target", "c": "Guarantee a minimum return to the target's management", "d": "Allow the acquirer to withdraw from the deal within 12 months", "answer": "b", "explanation": "Earnouts bridge valuation gaps by making part of the price contingent on the target achieving agreed performance targets post-acquisition.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Which of the following M&A failure risks is most associated with poor cultural integration?", "a": "Financial risk from over-leverage", "b": "Inability to retain key talent and realise people-dependent synergies", "c": "Regulatory rejection of the transaction", "d": "Goodwill impairment immediately after closing", "answer": "b", "explanation": "Cultural incompatibility is a leading cause of M&A failure, resulting in talent attrition and failure to capture human-capital-dependent synergies.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "The Herfindahl-Hirschman Index (HHI) is used by regulators to:", "a": "Value the target company in a merger", "b": "Measure market concentration and assess whether a merger will substantially reduce competition", "c": "Calculate synergies from a proposed merger", "d": "Determine the tax liability on a takeover", "answer": "b", "explanation": "HHI measures market concentration; a high HHI or large increase post-merger may trigger antitrust/competition concerns.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A merger of equals is characterised by:", "a": "One company paying a large premium to acquire a smaller target", "b": "Two similarly sized companies combining with shared governance", "c": "A hostile takeover by the larger company", "d": "The target company acquiring the bidder", "answer": "b", "explanation": "A merger of equals is typically structured as a deal between similarly sized companies, often with equal board representation.", "difficulty": "Easy"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Regulatory approval is required for M&A deals in Ghana from:", "a": "Only the SEC Ghana", "b": "Relevant sectoral regulators (e.g., Bank of Ghana for banking deals) and the Fair Competition Authority", "c": "Ghana Stock Exchange only", "d": "The President of Ghana's office", "answer": "b", "explanation": "M&A in Ghana may require approval from the sectoral regulator (e.g., BoG for banks, NIC for insurers) and the FCA for competition review.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "The difference between the acquisition price and the target's pre-deal market value is the:", "a": "Control premium", "b": "Synergy value", "c": "EV/EBITDA multiple", "d": "Minority discount", "answer": "a", "explanation": "The control premium is the amount paid above the standalone market value to gain full control of the target company.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A spin-off in corporate finance refers to:", "a": "A company acquiring a new business unit", "b": "A parent company distributing shares of a subsidiary to its existing shareholders as a separate listed entity", "c": "Selling a division to a private equity firm", "d": "Merging two subsidiaries into one", "answer": "b", "explanation": "A spin-off creates an independent public company by distributing subsidiary shares to the parent's shareholders.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Management buyout (MBO) involves:", "a": "External private equity acquiring a company", "b": "The existing management team buying the company from its current owners, often using debt", "c": "The company buying back its own shares from the market", "d": "Institutional shareholders taking control of the board", "answer": "b", "explanation": "In an MBO, incumbent management acquires ownership of the business from existing owners, typically with PE backing and significant debt.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Deal structure (cash vs. stock consideration) in an acquisition matters because:", "a": "Cash deals always create more synergies", "b": "Stock deals may dilute acquirer shareholders if shares are issued but reduce immediate cash strain", "c": "Cash deals require SEC approval while stock deals do not", "d": "Stock consideration is always cheaper for the acquirer", "answer": "b", "explanation": "Stock consideration issues new shares (diluting existing holders) while cash depletes the acquirer's balance sheet; each involves trade-offs.", "difficulty": "Hard"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Cross-border M&A introduces additional risks including:", "a": "Higher domestic interest rates", "b": "Currency risk, political risk, different legal systems, and cultural differences", "c": "Reduced diversification benefits", "d": "Increased transparency and regulatory certainty", "answer": "b", "explanation": "Cross-border deals face additional complexity from FX exposure, political/regulatory differences, and cultural integration challenges.", "difficulty": "Medium"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "Goodwill arises in an acquisition when:", "a": "The target's net assets exceed the purchase price", "b": "The purchase price exceeds the fair value of identifiable net assets acquired", "c": "The acquirer writes up assets to fair value", "d": "The target has brand recognition in the market", "answer": "b", "explanation": "Goodwill = Purchase price - FV of net identifiable assets; it represents intangible value such as brand, relationships, and synergies.", "difficulty": "Easy"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A management presentation in M&A is:", "a": "A board resolution approving the deal terms", "b": "An in-depth briefing by target management to potential acquirers to showcase the business and strategic rationale", "c": "A regulatory filing with the securities regulator", "d": "A public announcement of the deal to the stock exchange", "answer": "b", "explanation": "The management presentation allows the target's leadership to pitch the business case, strategy, and financials to potential buyers.", "difficulty": "Easy"},
    {"chapter": "Mergers and Acquisitions", "chapter_num": 9, "question": "A data room in M&A is:", "a": "A physical location where board meetings are held", "b": "A secure environment (virtual or physical) where confidential due diligence documents are shared with potential acquirers", "c": "The IT infrastructure of the target company", "d": "A database of all M&A transactions globally", "answer": "b", "explanation": "The data room provides bidders with access to confidential information under strict confidentiality agreements during due diligence.", "difficulty": "Easy"},

