    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "The Ghana Fixed Income Market (GFIM) is regulated by:", "a": "Bank of Ghana exclusively", "b": "SEC Ghana in conjunction with Bank of Ghana (for government securities)", "c": "Ghana Stock Exchange only", "d": "Ministry of Finance directly", "answer": "b", "explanation": "GFIM operates under joint oversight of SEC Ghana (for corporate bonds) and Bank of Ghana (for government securities).", "difficulty": "Medium"},
    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "The Investment Adviser Regulations under Act 929 require investment advisers to:", "a": "Guarantee a minimum return to clients", "b": "Disclose conflicts of interest, provide suitable recommendations, and maintain client confidentiality", "c": "Obtain approval from the Bank of Ghana before advising on any product", "d": "Only advise institutional clients", "answer": "b", "explanation": "Investment advisers must meet conduct standards including conflict disclosure, suitability assessment, and confidentiality obligations.", "difficulty": "Medium"},
    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "Which regulatory principle requires financial institutions to have systems to identify, assess, and mitigate risks?", "a": "The principle of transparency", "b": "The principle of sound risk management", "c": "The principle of equal treatment", "d": "The principle of minimum capital", "answer": "b", "explanation": "Sound risk management requires firms to have robust frameworks for identifying, measuring, monitoring, and controlling risks.", "difficulty": "Easy"},
    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "International Financial Reporting Standards (IFRS) are adopted in Ghana to:", "a": "Align Ghana's tax law with international practice", "b": "Ensure financial statements are prepared on a consistent, internationally comparable basis", "c": "Reduce the tax burden on listed companies", "d": "Simplify the audit process for small companies", "answer": "b", "explanation": "IFRS adoption ensures Ghana's financial statements are globally comparable, improving investor confidence and access to capital.", "difficulty": "Easy"},
    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "Systemic risk regulation (macroprudential policy) aims to:", "a": "Protect individual investors from poor investment decisions", "b": "Safeguard the stability of the entire financial system, not just individual firms", "c": "Set maximum interest rates on loans", "d": "Regulate foreign direct investment into Ghana", "answer": "b", "explanation": "Macroprudential regulation monitors and mitigates risks to the financial system as a whole, including contagion and procyclicality.", "difficulty": "Medium"},
    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "The Ghana Deposit Protection Act provides:", "a": "Insurance coverage for investments in mutual funds", "b": "Limited deposit insurance protection for depositors at licensed deposit-taking institutions", "c": "Unlimited government guarantee on all bank deposits", "d": "Protection against losses on equity investments", "answer": "b", "explanation": "Deposit protection schemes cover depositors up to a specified limit, maintaining public confidence in the banking system.", "difficulty": "Easy"},
    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "The 'Twin Peaks' regulatory model adopted by some countries separates regulation into:", "a": "Banking regulation and securities regulation", "b": "Prudential regulation (financial safety/soundness) and conduct regulation (customer treatment)", "c": "Domestic regulation and international regulation", "d": "Public and private sector regulation", "answer": "b", "explanation": "Twin Peaks separates prudential (safety and soundness) from conduct of business regulation, each handled by a dedicated regulator.", "difficulty": "Hard"},
    {"chapter": "Regulatory Framework", "chapter_num": 10, "question": "Under Ghana's securities laws, insider dealing becomes an offence when:", "a": "Any director buys shares in their own company", "b": "A person trades in securities using material, non-public information obtained through their position", "c": "A fund manager buys shares after a public recommendation", "d": "An investor purchases shares without a broker", "answer": "b", "explanation": "Insider dealing requires both possession of material non-public information and trading on it — not all director trades are illegal.", "difficulty": "Medium"},
